insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2f68a77c-5c33-5cc4-a78a-b35523d871ac', 'Each original strand acts as a template, and only the complementary nucleotide can pair with each base [1], so the new strands have exactly the right sequence and two identical DNA molecules are produced [1].', 'Each original strand acts as a template, and only the complementary nucleotide can pair with each base [1], so the new strands have exactly the right sequence and two identical DNA molecules are produced [1].', '[{"text": "Marking point 1", "any": ["template", "each strand"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["identical", "accurate", "same sequence", "copy"], "all": [], "marks": 1}]'::jsonb, 'Each original strand acts as a template, and only the complementary nucleotide can pair with each base [1], so the new strands have exactly the right sequence and two identical DNA molecules are produced [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
