insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('77873426-d978-593c-b510-a12c67f72e50', 'Each base pairs only with its partner: A with T and C with G [1]; so the sequence of one strand determines the sequence of the other [1].', 'Each base pairs only with its partner: A with T and C with G [1]; so the sequence of one strand determines the sequence of the other [1].', '[{"text": "Marking point 1", "any": ["a with t", "a-t", "a pairs", "adenine"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sequence", "determine", "one strand", "predict"], "all": [], "marks": 1}]'::jsonb, 'Each base pairs only with its partner: A with T and C with G [1]; so the sequence of one strand determines the sequence of the other [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
