insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6302fee5-e6f3-5741-9270-bd70cba216ae', 'DNA has deoxyribose, RNA ribose [1]; DNA has thymine, RNA uracil [1]; DNA is double-stranded, RNA single-stranded [1].', 'DNA has deoxyribose, RNA ribose [1]; DNA has thymine, RNA uracil [1]; DNA is double-stranded, RNA single-stranded [1].', '[{"text": "Marking point 1", "any": ["deoxyribose", "ribose"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["thymine", "uracil"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["double", "single", "strand"], "all": [], "marks": 1}]'::jsonb, 'DNA has deoxyribose, RNA ribose [1]; DNA has thymine, RNA uracil [1]; DNA is double-stranded, RNA single-stranded [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
