insert into public.questions (id, kind, prompt, options, marks) values ('2f68a77c-5c33-5cc4-a78a-b35523d871ac', 'short', 'Explain the importance of complementary base pairing in DNA replication. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2f68a77c-5c33-5cc4-a78a-b35523d871ac', 'Each original strand acts as a template, and only the complementary nucleotide can pair with each base [1], so the new strands have exactly the right sequence and two identical DNA molecules are produced [1].', 'Each original strand acts as a template, and only the complementary nucleotide can pair with each base [1], so the new strands have exactly the right sequence and two identical DNA molecules are produced [1].', '[{"text": "Marking point 1", "any": ["template", "each strand"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["identical", "accurate", "same sequence", "copy"], "all": [], "marks": 1}]'::jsonb, 'Each original strand acts as a template, and only the complementary nucleotide can pair with each base [1], so the new strands have exactly the right sequence and two identical DNA molecules are produced [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de7ba77d-e3bf-5d2b-9ea2-b04da5f50ee1', '2f68a77c-5c33-5cc4-a78a-b35523d871ac', 22);
insert into public.questions (id, kind, prompt, options, marks) values ('77873426-d978-593c-b510-a12c67f72e50', 'short', 'Explain why the two strands of DNA are described as complementary. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('77873426-d978-593c-b510-a12c67f72e50', 'Each base pairs only with its partner: A with T and C with G [1]; so the sequence of one strand determines the sequence of the other [1].', 'Each base pairs only with its partner: A with T and C with G [1]; so the sequence of one strand determines the sequence of the other [1].', '[{"text": "Marking point 1", "any": ["a with t", "a-t", "a pairs", "adenine"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sequence", "determine", "one strand", "predict"], "all": [], "marks": 1}]'::jsonb, 'Each base pairs only with its partner: A with T and C with G [1]; so the sequence of one strand determines the sequence of the other [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de7ba77d-e3bf-5d2b-9ea2-b04da5f50ee1', '77873426-d978-593c-b510-a12c67f72e50', 23);
