insert into public.questions (id, kind, prompt, options, marks) values ('249edf05-6a28-581e-a752-8a915624c1c2', 'short', 'Explain how DNA can store a vast amount of information with only four bases. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('249edf05-6a28-581e-a752-8a915624c1c2', 'The information is in the sequence of bases, and any base can follow any other [1]; DNA molecules are very long, so the number of possible sequences (4ⁿ) is enormous [1].', 'The information is in the sequence of bases, and any base can follow any other [1]; DNA molecules are very long, so the number of possible sequences (4ⁿ) is enormous [1].', '[{"text": "Marking point 1", "any": ["sequence", "order", "any order", "no restriction"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["4", "long", "length", "number of possible", "combination"], "all": [], "marks": 1}]'::jsonb, 'The information is in the sequence of bases, and any base can follow any other [1]; DNA molecules are very long, so the number of possible sequences (4ⁿ) is enormous [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
