insert into public.questions (id, kind, prompt, options, marks) values ('4af667d5-c53b-5ffc-8fc3-b6542cad3317', 'short', 'Explain why 64 codons can code for only 20 amino acids. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4af667d5-c53b-5ffc-8fc3-b6542cad3317', 'Most amino acids are coded for by more than one codon (the code is degenerate) [1]; and three codons are stop codons that code for no amino acid [1].', 'Most amino acids are coded for by more than one codon (the code is degenerate) [1]; and three codons are stop codons that code for no amino acid [1].', '[{"text": "Marking point 1", "any": ["more than one", "several codons", "degenerate", "redundan"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["stop"], "all": [], "marks": 1}]'::jsonb, 'Most amino acids are coded for by more than one codon (the code is degenerate) [1]; and three codons are stop codons that code for no amino acid [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
