insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7261c73a-11bb-5ae3-80fa-e551043254e3', 'Almost all organisms use the same genetic code, with the same codons for the same amino acids [1]; this is best explained by all organisms inheriting it from a common ancestor [1].', 'Almost all organisms use the same genetic code, with the same codons for the same amino acids [1]; this is best explained by all organisms inheriting it from a common ancestor [1].', '[{"text": "Marking point 1", "any": ["same", "universal", "shared", "all organisms"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ancestor", "inherit", "evolved once"], "all": [], "marks": 1}]'::jsonb, 'Almost all organisms use the same genetic code, with the same codons for the same amino acids [1]; this is best explained by all organisms inheriting it from a common ancestor [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
