insert into public.questions (id, kind, prompt, options, marks) values ('4956a838-bc76-5f2e-b44d-600eff1e8e16', 'short', 'Distinguish between replication on the leading strand and the lagging strand.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4956a838-bc76-5f2e-b44d-600eff1e8e16', 'The leading strand is synthesised continuously towards the fork [1]; the lagging strand is synthesised discontinuously in Okazaki fragments away from the fork [1]; the leading strand needs an RNA primer only once, the lagging strand needs a new primer for each fragment [1].', 'The leading strand is synthesised continuously towards the fork [1]; the lagging strand is synthesised discontinuously in Okazaki fragments away from the fork [1]; the leading strand needs an RNA primer only once, the lagging strand needs a new primer for each fragment [1].', '[{"text": "Marking point 1", "any": ["continuous", "continuously"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["okazaki", "discontinuous", "fragments"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["one primer", "many primers", "each fragment", "repeatedly"], "all": [], "marks": 1}]'::jsonb, 'The leading strand is synthesised continuously towards the fork [1]; the lagging strand is synthesised discontinuously in Okazaki fragments away from the fork [1]; the leading strand needs an RNA primer only once, the lagging strand needs a new primer for each fragment [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('d7f87a79-7a57-583a-b88d-3c7f02dca5b2', '4956a838-bc76-5f2e-b44d-600eff1e8e16', 27);
