insert into public.questions (id, kind, prompt, options, marks) values ('616c6881-2cb3-57d3-b738-6533a3a25165', 'short', 'Explain why the lagging strand is synthesised as Okazaki fragments.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('616c6881-2cb3-57d3-b738-6533a3a25165', 'The two strands are antiparallel [1]; DNA polymerase can only add nucleotides to the 3'' end, building 5''→3'' [1]; on the lagging strand this is away from the fork, so short fragments are made each time more of the template is exposed [1].', 'The two strands are antiparallel [1]; DNA polymerase can only add nucleotides to the 3'' end, building 5''→3'' [1]; on the lagging strand this is away from the fork, so short fragments are made each time more of the template is exposed [1].', '[{"text": "Marking point 1", "any": ["antiparallel", "opposite direction"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["only add to the 3''", "5'' to 3''", "3'' end"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["away from the fork", "short", "as it opens", "fork"], "all": [], "marks": 1}]'::jsonb, 'The two strands are antiparallel [1]; DNA polymerase can only add nucleotides to the 3'' end, building 5''→3'' [1]; on the lagging strand this is away from the fork, so short fragments are made each time more of the template is exposed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
