insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('67c7cea9-ba8b-56a0-be9a-655f74c7f175', 'Taq polymerase is heat-stable (from a hot-spring bacterium) [1]; it is not denatured at 95 °C during the denaturation step, so it can work through every cycle without being replaced [1].', 'Taq polymerase is heat-stable (from a hot-spring bacterium) [1]; it is not denatured at 95 °C during the denaturation step, so it can work through every cycle without being replaced [1].', '[{"text": "Marking point 1", "any": ["heat-stable", "heat stable", "thermostable", "not denatured", "hot spring", "high temperature"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["95", "each cycle", "repeated", "denaturation"], "all": [], "marks": 1}]'::jsonb, 'Taq polymerase is heat-stable (from a hot-spring bacterium) [1]; it is not denatured at 95 °C during the denaturation step, so it can work through every cycle without being replaced [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
