insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cd0e0406-c0cd-52aa-a0ad-91ebd6702afa', 'DNA is negatively charged because of its phosphate groups [1]; in an electric field it moves towards the positive electrode [1]; smaller fragments move faster through the pores of the gel, so fragments are separated by size [1].', 'DNA is negatively charged because of its phosphate groups [1]; in an electric field it moves towards the positive electrode [1]; smaller fragments move faster through the pores of the gel, so fragments are separated by size [1].', '[{"text": "Marking point 1", "any": ["negative", "phosphate"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["positive", "anode", "electric"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["small", "size", "further", "faster"], "all": [], "marks": 1}]'::jsonb, 'DNA is negatively charged because of its phosphate groups [1]; in an electric field it moves towards the positive electrode [1]; smaller fragments move faster through the pores of the gel, so fragments are separated by size [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
