insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('61f28b94-e22a-503d-b5fe-5c4bcf6e554c', 'Primers are short sequences complementary to the ends of the target DNA, which bind (anneal) to it [1]; they select the section to be copied and provide a starting point for Taq polymerase [1].', 'Primers are short sequences complementary to the ends of the target DNA, which bind (anneal) to it [1]; they select the section to be copied and provide a starting point for Taq polymerase [1].', '[{"text": "Marking point 1", "any": ["complementary", "bind", "anneal"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["start", "starting point", "polymerase", "which section", "target", "specific"], "all": [], "marks": 1}]'::jsonb, 'Primers are short sequences complementary to the ends of the target DNA, which bind (anneal) to it [1]; they select the section to be copied and provide a starting point for Taq polymerase [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
