insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ac4253fd-f175-5d20-8127-3a90cd36a105', 'A base substitution changes the codon GAG to GUG in the mRNA [1]; so glutamic acid [1] is replaced by valine in the β chain of haemoglobin [1]; the altered haemoglobin forms fibres at low O₂, giving sickle-shaped red blood cells that block capillaries [1].', 'A base substitution changes the codon GAG to GUG in the mRNA [1]; so glutamic acid [1] is replaced by valine in the β chain of haemoglobin [1]; the altered haemoglobin forms fibres at low O₂, giving sickle-shaped red blood cells that block capillaries [1].', '[{"text": "Marking point 1", "any": ["codon changes", "a to t", "cac"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["glutamic", "glutamate"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["valine"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["sickle", "stick together", "fibres", "insoluble"], "all": [], "marks": 1}]'::jsonb, 'A base substitution changes the codon GAG to GUG in the mRNA [1]; so glutamic acid [1] is replaced by valine in the β chain of haemoglobin [1]; the altered haemoglobin forms fibres at low O₂, giving sickle-shaped red blood cells that block capillaries [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
