insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4dd7b6d7-6619-5e46-99e0-300e62ce11d4', 'Each codon has three bases [1]; 4³ = 64 codons, more than enough for 20 amino acids [1]; so most amino acids are coded for by more than one codon, which is why it is degenerate [1].', 'Each codon has three bases [1]; 4³ = 64 codons, more than enough for 20 amino acids [1]; so most amino acids are coded for by more than one codon, which is why it is degenerate [1].', '[{"text": "Marking point 1", "any": ["three bases", "3 bases"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["64", "20"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["more than one codon", "several codons", "same amino acid"], "all": [], "marks": 1}]'::jsonb, 'Each codon has three bases [1]; 4³ = 64 codons, more than enough for 20 amino acids [1]; so most amino acids are coded for by more than one codon, which is why it is degenerate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
